static void test_l90_psl_pairs(void) {
    TEST_ASSERT_EQUAL(1, wf_regdom_same_site("x.a.b.ck", "y.a.b.ck"));
    TEST_ASSERT_EQUAL(0, wf_regdom_same_site("a.b.ck", "c.b.ck"));
    TEST_ASSERT_EQUAL(1, wf_regdom_same_site("www.ck", "x.www.ck"));
    TEST_ASSERT_EQUAL(1, wf_regdom_same_site("x.city.kawasaki.jp", "city.kawasaki.jp"));
    TEST_ASSERT_EQUAL(0, wf_regdom_same_site("a.ward.kawasaki.jp", "b.ward.kawasaki.jp"));
    TEST_ASSERT_EQUAL(1, wf_regdom_same_site("x.a.ward.kawasaki.jp", "y.a.ward.kawasaki.jp"));
    TEST_ASSERT_EQUAL(0, wf_regdom_same_site("a.myschool.sch.uk", "b.myschool.sch.uk"));
    TEST_ASSERT_EQUAL(1, wf_regdom_same_site("x.a.myschool.sch.uk", "y.a.myschool.sch.uk"));
    TEST_ASSERT_EQUAL(0, wf_regdom_same_site("me.github.io", "you.github.io"));
    TEST_ASSERT_EQUAL(1, wf_regdom_same_site("www.example.co.mu", "login.example.co.mu"));
}

